import React from "react";
import PropTypes from "prop-types";
import { Select } from "@traveloka/soya-components";

class DropdownInput extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      value: props.value === null ? props.items[0].value : props.value,
    };
  }

  componentDidUpdate(prevProps) {
    if (prevProps.value !== this.props.value) {
      this.setState({
        value: this.props.value || "true",
      });
    }
  }

  shouldComponentUpdate(nextProps, nextState) {
    let result = false;
    if (
      nextProps.value !== this.props.value ||
      nextState.value !== this.state.value
    ) {
      result = true;
    }
    return result;
  }

  render() {
    const { items } = this.props;
    let defaultValue = items[0];
    for (const i in items) {
      if (items[i].value === this.state.value) {
        defaultValue = items[i];
      }
    }
    return (
      <Select
        options={items}
        defaultValue={defaultValue}
        searchable
        backspaceRemoves
        onChange={this.handleOnSelect}
      />
    );
  }

  handleOnSelect = (value) => {
    const { onChange, name } = this.props;
    this.setState({ value });

    if (onChange) {
      onChange(name, value);
    }
  };
}

DropdownInput.propTypes = {
  name: PropTypes.string.isRequired,
  onChange: PropTypes.func,
  items: PropTypes.array.isRequired,
  value: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
};

export default DropdownInput;
